class EditorMemento {
  // Fields are conventionally private; only Editor is meant to read them.
  #text;
  #cursor;

  constructor(text, cursor) {
    this.#text = text;
    this.#cursor = cursor;
  }

  // Package-private access point: only Editor calls this.
  _getState() {
    return { text: this.#text, cursor: this.#cursor };
  }
}

class Editor {
  #text = '';
  #cursor = 0;

  type(chars) {
    this.#text = this.#text.slice(0, this.#cursor) + chars + this.#text.slice(this.#cursor);
    this.#cursor += chars.length;
  }

  save() {
    // Originator builds its own memento; nobody else can construct one meaningfully.
    return new EditorMemento(this.#text, this.#cursor);
  }

  restore(memento) {
    const { text, cursor } = memento._getState();
    this.#text = text;
    this.#cursor = cursor;
  }

  get text() { return this.#text; }
}

