class EditorMemento:
    def __init__(self, text, cursor):
        # Leading underscore signals "internal, do not touch"
        self._text = text
        self._cursor = cursor

    def _get_state(self):
        return self._text, self._cursor


class Editor:
    def __init__(self):
        self._text = ""
        self._cursor = 0

    def type(self, chars):
        self._text = self._text[:self._cursor] + chars + self._text[self._cursor:]
        self._cursor += len(chars)

    def save(self):
        return EditorMemento(self._text, self._cursor)

    def restore(self, memento):
        self._text, self._cursor = memento._get_state()

    @property
    def text(self):
        return self._text


if __name__ == "__main__":
    editor = Editor()
    editor.type("Hello")
    saved = editor.save()

    editor.type(", world")
    print(editor.text)  # Hello, world

    editor.restore(saved)
    print(editor.text)  # Hello

