final class EditorMemento {
    private final String text;
    private final int cursor;

    // Package-private constructor: only Editor (same package) can create one.
    EditorMemento(String text, int cursor) {
        this.text = text;
        this.cursor = cursor;
    }

    String getText() { return text; }
    int getCursor() { return cursor; }
}

class Editor {
    private String text = "";
    private int cursor = 0;

    void type(String chars) {
        text = text.substring(0, cursor) + chars + text.substring(cursor);
        cursor += chars.length();
    }

    EditorMemento save() {
        return new EditorMemento(text, cursor);
    }

    void restore(EditorMemento memento) {
        this.text = memento.getText();
        this.cursor = memento.getCursor();
    }

    String getText() { return text; }
}

public class Main {
    public static void main(String[] args) {
        Editor editor = new Editor();
        editor.type("Hello");
        EditorMemento saved = editor.save();

        editor.type(", world");
        System.out.println(editor.getText()); // Hello, world

        editor.restore(saved);
        System.out.println(editor.getText()); // Hello
    }
}

