// Restated from the Editor/EditorMemento shown earlier in this
// topic, included here so this example can run on its own
#include <iostream>
#include <string>
#include <stack>

class EditorMemento {
private:
    std::string text;
    int cursor;

    EditorMemento(const std::string& text, int cursor) : text(text), cursor(cursor) {}

    friend class Editor;

public:
    std::string getText() const { return text; }
    int getCursor() const { return cursor; }
};

class Editor {
private:
    std::string text;
    int cursor = 0;

public:
    void type(const std::string& chars) {
        text = text.substr(0, cursor) + chars + text.substr(cursor);
        cursor += static_cast<int>(chars.size());
    }

    EditorMemento save() const {
        return EditorMemento(text, cursor);
    }

    void restore(const EditorMemento& memento) {
        text = memento.getText();
        cursor = memento.getCursor();
    }

    std::string getText() const { return text; }
};

class History {
private:
    Editor& editor;
    std::stack<EditorMemento> undoStack;
    std::stack<EditorMemento> redoStack;

public:
    explicit History(Editor& editor) : editor(editor) {}

    void recordBeforeEdit() {
        undoStack.push(editor.save());
        while (!redoStack.empty()) redoStack.pop();
    }

    void undo() {
        if (undoStack.empty()) return;
        redoStack.push(editor.save());
        EditorMemento memento = undoStack.top();
        undoStack.pop();
        editor.restore(memento);
    }

    void redo() {
        if (redoStack.empty()) return;
        undoStack.push(editor.save());
        EditorMemento memento = redoStack.top();
        redoStack.pop();
        editor.restore(memento);
    }
};

int main() {
    Editor editor;
    History history(editor);

    history.recordBeforeEdit();
    editor.type("Hello");

    history.recordBeforeEdit();
    editor.type(", world");

    std::cout << editor.getText() << std::endl; // Hello, world
    history.undo();
    std::cout << editor.getText() << std::endl; // Hello
    history.redo();
    std::cout << editor.getText() << std::endl; // Hello, world
    return 0;
}
